theorem lg_target {x : ℝ} (hx : 1 < x) : ↑⌊x⌋₊.primeCounting ≤ Real.log 4 * x / Real.log √x + √x := by
  let f := fun x => √x * Real.log x
  let g := fun x => Real.log 4 * x / Real.log √x + √x
  have h_f_deriv : deriv f = fun x => (2 + Real.log x) / (2 * √x) := deriv_sqrt_mul_log
  have h_f_deriv_at : HasDerivAt f ((2 + Real.log x) / (2 * √x)) x := hasDerivAt_sqrt_mul_log hx
  let h_g_deriv : deriv g = fun x => Real.log 4 / Real.log √x - Real.log 4 * x / (Real.log √x)^2 * (1 / (2 * √x)) + 1/(2 * √x) :=
    by
      let log_sqrt_x := Real.log √x
      let log_4 := Real.log 4
      let g' := fun x => log_4 * x / log_sqrt_x + √x
      have h_log_sqrt_x : log_sqrt_x = Real.log x / 2 := Real.log_sqrt (by linarith)
      let g' := fun x => log_4 * x / (Real.log x / 2) + √x
      simp only [h_log_sqrt_x, div_div_eq_div_mul_right, mul_div_assoc]
      have h_g_deriv1 : deriv (fun x => log_4 * x / (Real.log x / 2)) x =
        log_4 / (Real.log x / 2) - log_4 * x * deriv (fun x => Real.log x / 2) x / (Real.log x / 2)^2
      let h_deriv_log_x : deriv (fun x => Real.log x) x = 1 / x := by apply_instance
      let h_deriv_log_x_over_2 : deriv (fun x => Real.log x / 2) x = (1 / x) / 2 := by simp
      simp only [h_g_deriv1, h_deriv_log_x_over_2, h_deriv_log_x, mul_div_assoc, div_div_eq_div_mul_right]
      let h_g_deriv2 : deriv (fun x => √x) x = 1 / (2 * √x) := by apply_instance
      simp only [h_g_deriv2]
      exact rfl
  have h_g_deriv_at : HasDerivAt g (Real.log 4 / Real.log √x - Real.log 4 * x / (Real.log √x)^2 * (1 / (2 * √x)) + 1/(2 * √x)) x :=
    by apply_instance
